    stack = []
    result = []
    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack or stack[-1] != '(':
                raise ValueError("Invalid parenthesis string")
            stack.pop()
            result.append(''.join(stack))
            stack = []
    return result
